NIT: With the change to a vector constructor, this can be simplified. 

```suggestion
    const CTransaction creationTx{
        {CTxIn{COutPoint{}}},
        {CTxOut{1, scriptPubKey}},
        /*version=*/ 1,
    };
    const CTransaction spendingTx{
        {CTxIn{COutPoint{creationTx.GetHash(), 0}, scriptSig, CTxIn::SEQUENCE_FINAL, witness}},
        {CTxOut{1, CScript{}}},
        /*version=*/ 1,
    };

    AddCoins(coins, creationTx, /*nHeight=*/ 0);
    return {creationTx, spendingTx};
```

